// Parking sensor: beeps faster as a hand comes closer
const int TRIG = 9;
const int ECHO = 10;
const int BUZZER = 8;
float cm = -1;
unsigned long lastPing = 0, lastBeep = 0, lastPrint = 0;

float ping() {
  digitalWrite(TRIG, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG, HIGH);   // a HIGH of at least 10 µs starts one ping
  delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  unsigned long us = pulseIn(ECHO, HIGH, 30000UL);   // give up after 30 ms (about 5 m): 0 means no echo
  if (us == 0) return -1;
  return us / 58.0;   // 58 µs of round trip per cm
}

void setup() {
  Serial.begin(9600);
  pinMode(TRIG, OUTPUT);
  pinMode(ECHO, INPUT);
  Serial.println("parking sensor: beeps faster as you get closer");
}

void loop() {
  unsigned long now = millis();
  if (now - lastPing >= 60) {   // at least 60 ms between pings, so the last echo has died away
    lastPing = now;
    cm = ping();
  }
  if (cm < 0 || cm > 100) noTone(BUZZER);
  else if (cm < 10) tone(BUZZER, 2000);   // under 10 cm: one long tone
  else if (now - lastBeep >= cm * 10) {    // a 50 ms beep every cm x 10 ms: faster as it gets closer
    lastBeep = now;
    tone(BUZZER, 2000, 50);
  }
  if (now - lastPrint >= 1000) {
    lastPrint = now;
    if (cm < 0) Serial.println("no echo");
    else {
      Serial.print(cm, 2);
      if (cm < 10) Serial.println(" cm: STOP");
      else if (cm <= 100) {
        Serial.print(" cm: beep every ");
        Serial.print((int)(cm * 10));
        Serial.println(" ms");
      } else Serial.println(" cm");
    }
  }
}

// Ping and print, pointed at a cushion 40 cm away
const int TRIG = 9;
const int ECHO = 10;

float ping() {
  digitalWrite(TRIG, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG, HIGH);   // a HIGH of at least 10 µs starts one ping
  delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  unsigned long us = pulseIn(ECHO, HIGH, 30000UL);   // give up after 30 ms (about 5 m): 0 means no echo
  if (us == 0) return -1;
  return us / 58.0;   // 58 µs of round trip per cm
}

void setup() {
  Serial.begin(9600);
  pinMode(TRIG, OUTPUT);
  pinMode(ECHO, INPUT);
  Serial.println("hc-sr04: one ping a second");
}

void loop() {
  float cm = ping();
  if (cm < 0) {
    Serial.println("no echo");   // 0 is not "very close": nothing came back
  } else {
    Serial.print(cm, 2);
    Serial.println(" cm");
  }
  delay(1000);
}

